// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        vm.assume(blockNum > 0);
        vm.assume(timestamp > 0);
        vm.roll(blockNum);
        vm.warp(timestamp);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        uint256 balance = address(c).balance;
        bool isDivisibleBy15 = (blockNum % 15 == 0);
        assertTrue((balance == 0) == isDivisibleBy15);
    }
}
